SELECT board_skin_id, title, NICKNAME,content,hit,elike,reip,bdate,imgn,row_num FROM (
SELECT board_skin_id, title, NICKNAME,content,hit,elike,reip,bdate,imgn, ROW_NUMBER()
OVER(ORDER BY board_skin_id desc) AS row_num FROM board_skin


                AND member_num = #{num}




                        AND NICKNAME LIKE '%' || #{searchValue} || '%'


                        AND title LIKE '%' || #{searchValue} || '%'


                        AND content LIKE '%' || #{searchValue} || '%'




) numbered_rows WHERE row_num BETWEEN #{begin} AND #{end}

SELECT BOARD_SKIN_ID as board_skin_id, title, NICKNAME as writer,
content, imgn, hit, elike, reip, bdate
FROM board_skin WHERE board_skin_id=#{num}
